  "test": "import logging
import pytest

from browser_use.browser.watchdogs.popups_watchdog import PopupsWatchdog

class DummyCDPClient:
    def __init__(self):
        self.send = self
        self.register = self

    class Page:
        @staticmethod
        async def enable(*args, **kwargs):
            pass

        @staticmethod
        async def handleJavaScriptDialog(*args, **kwargs):
            pass

    async def enable(self, *args, **kwargs):
        pass

    async def handleJavaScriptDialog(self, *args, **kwargs):
        pass

    @staticmethod
    def javascriptDialogOpening(handler):
        pass

    @property
    def Page(self):
        return self

class DummySession:
    def __init__(self):
        self._closed_popup_messages = []
        self._cdp_client_root = None
        self.logger = logging.getLogger("dummy")

    async def get_or_create_cdp_session(self, target_id, focus=False):
        class Dummy:
            session_id = "sess123"
            cdp_client = DummyCDPClient()
        return Dummy()

class DummyEvent:
    def __init__(self, target_id):
        self.target_id = target_id

@pytest.mark.asyncio
async def test_popups_watchdog_dialog_logging_is_debug(caplog):
    dummy_browser = DummySession()
    watchdog = PopupsWatchdog()
    watchdog.browser_session = dummy_browser
    event = DummyEvent("target1")
    caplog.set_level(logging.DEBUG)
    await watchdog.on_TabCreatedEvent(event)
    # Ensure a JavaScript dialog log entry exists and is at DEBUG level
    found = False
    for rec in caplog.records:
        if "JavaScript" in rec.message:
            found = True
            assert rec.levelno == logging.DEBUG
    assert found, "Expected a JavaScript dialog log message""
}
